type lane=Mechanical_value|Ownership
type package=Stage_values|Barrier|Device_identity|Label|Debug_group
type item={id:string;lane:lane;package:package;operation:string;tests:string list}
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify~kind id=if kind="enum-case"then{id;lane=Mechanical_value;package=Stage_values;operation="Metal.Enum.Mtl_stages";tests=["SDK numeric static_assert";"flags round trip";"availability"]}else let package,operation,tests=if contains id "barrierAfter"then Barrier,"Metal.Command_encoder.barrier",["nonempty/known stage masks";"encoder state"]else if contains id " device]"||contains id ":device"then Device_identity,"Metal.Command_encoder.device",["safe owner identity";"destroyed rejection"]else if contains id "Debug"||contains id "debug"then Debug_group,"Metal.Command_encoder debug groups",["NUL rejection";"balanced stack state"]else Label,"Metal.Command_encoder.label",["nullable UTF-8 round trip";"lifetime"]in{id;lane=Ownership;package;operation;tests}
let validate items=let count f=List.length(List.filter f items)in if List.length items<>18||count(fun x->x.lane=Mechanical_value)<>9||count(fun x->x.lane=Ownership)<>9||List.map(fun p->count(fun x->x.package=p))[Stage_values;Barrier;Device_identity;Label;Debug_group]<>[9;1;2;3;3]then failwith"CommandEncoder18 tail drift"
